#!/usr/bin/env node
/**
 * Pre-commit: enforce migration file boundaries.
 *
 * Migration files are now organized into two subdirectories:
 *   versions/ddl/  — auto-generated schema changes (no op.execute)
 *   versions/data/ — hand-written data migrations (with data_only marker)
 *
 * Rules:
 *   1. Files in ddl/ that contain the autogenerate marker
 *      MUST NOT contain op.execute() calls.
 *   2. Files in data/ MUST contain "# Manual override reason: data_only"
 *      in the module docstring.
 */
const { execSync } = require("node:child_process");
const { readFileSync } = require("node:fs");
const path = require("node:path");

const ROOT = execSync("git rev-parse --show-toplevel", { encoding: "utf-8" }).trim();
const DDL_DIR = path.join(ROOT, "backend", "migrations", "versions", "ddl");
const DATA_DIR = path.join(ROOT, "backend", "migrations", "versions", "data");

const staged = execSync(
  `git diff --cached --name-only --diff-filter=ACM -- "${DDL_DIR}/*.py" "${DATA_DIR}/*.py"`,
  { encoding: "utf-8" },
).trim();

if (!staged) process.exit(0);

const files = staged.split("\n").filter(Boolean);
const AUTOGEN_MARKER = "# ### commands auto generated by Alembic";
const REASON_PREFIX = "# Manual override reason:";
const VALID_REASONS = ["data_only"];

let errors = 0;

for (const f of files) {
  const basename = path.basename(f);
  const rel = path.relative(ROOT, f);
  const content = readFileSync(f, "utf-8");
  const hasAutogen = content.includes(AUTOGEN_MARKER);
  const inDdl = f.startsWith(DDL_DIR);
  const inData = f.startsWith(DATA_DIR);

  if (inDdl && hasAutogen) {
    // Rule 1: autogenerated DDL must be pure DDL — no op.execute()
    if (/^\s+op\.execute\(/m.test(content)) {
      errors++;
      console.error([
        ``,
        `  ================================================================`,
        `  MIGRATION CHECK FAILED`,
        `  ================================================================`,
        `  File:  versions/ddl/${basename}`,
        `  Error: Autogenerated migration contains op.execute()`,
        `  Rule:  DDL migrations must NOT contain data ops.`,
        `         Create a separate data_only migration.`,
        `  ----------------------------------------------------------------`,
        `  Fix:`,
        `    1. Remove all op.execute() lines from this file`,
        `    2. Run:  pnpm run db:data "your_description"`,
        `    3. Move the op.execute() logic into the new file`,
        `    4. Run:  pnpm run db:migrate`,
        `  ================================================================`,
        ``,
      ].join("\n"));
    }
  }

  if (inData) {
    // Rule 2: data migrations must declare data_only reason
    const reasonLine = content
      .split("\n")
      .find((l) => l.trimStart().startsWith(REASON_PREFIX));
    const reason = reasonLine?.split(":")[1]?.trim();

    if (!reason || !VALID_REASONS.includes(reason)) {
      errors++;
      console.error([
        ``,
        `  ================================================================`,
        `  MIGRATION CHECK FAILED`,
        `  ================================================================`,
        `  File:  versions/data/${basename}`,
        `  Error: Missing "# Manual override reason: data_only" marker.`,
        `  Rule:  Data migrations must declare override reason.`,
        `  ----------------------------------------------------------------`,
        `  Fix:  Add to module docstring:`,
        `          # Manual override reason: data_only`,
        ``,
        `  ================================================================`,
        ``,
      ].join("\n"));
    }
  }
}

if (errors > 0) {
  console.error(`  ${errors} migration file(s) failed. See AGENTS.md § Migration Rules.\n`);
  process.exit(1);
}
